// <auto-generated>
// Campground.Shared — compiled into each Campground plugin as internal code.
// Edit it in AHouseOfBards/Campground-Coordination/shared, never inside a plugin.
// </auto-generated>
#nullable enable

using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Campground.Shared.Registry;

namespace Campground.Shared.Storage
{
    /// <summary>
    /// Deleting a Jellyfin user deletes what every Campground plugin keeps about them. Each plugin registers a
    /// cleaner; the plugin's <c>IEventConsumer&lt;UserDeletedEventArgs&gt;</c> calls <see cref="RunAsync"/>
    /// (see shared/README.md for the six-line consumer). The first call per user wins, so with several plugins
    /// installed the cleaners still run once.
    /// </summary>
    internal static class UserDataCleanup
    {
        private const string CleanersSection = "cleanup.cleaners";
        private const string DoneSection = "cleanup.done";

        /// <summary>Registers this plugin's cleaner.</summary>
        internal static void Register(string pluginId, Func<Guid, CancellationToken, Task> cleaner)
            => CampgroundRegistry.Section(CleanersSection)[pluginId] = cleaner;

        /// <summary>Runs every plugin's cleaner for the user, once. Returns the plugins whose cleaner failed.</summary>
        internal static async Task<IReadOnlyList<string>> RunAsync(Guid userId, CancellationToken ct = default)
        {
            // Claimed per plugin, so a cleaner that threw is tried again on the next call and the others don't rerun.
            var done = CampgroundRegistry.Section(DoneSection);
            var failed = new List<string>();
            var ran = false;
            foreach (var pair in CampgroundRegistry.Section(CleanersSection).ToArray())
            {
                if (pair.Value is not Func<Guid, CancellationToken, Task> cleaner)
                {
                    continue;
                }

                var claim = userId.ToString("N") + "|" + pair.Key;
                if (!done.TryAdd(claim, DateTime.UtcNow))
                {
                    continue;
                }

                ran = true;
                try
                {
                    await cleaner(userId, ct).ConfigureAwait(false);
                }
                catch (Exception)
                {
                    done.TryRemove(claim, out _);
                    failed.Add(pair.Key);
                }
            }

            if (ran)
            {
                CampgroundEvents.Publish(EventNames.UserDeleted, new { userId, failed });
            }

            return failed;
        }
    }
}
